sys_script.script:
(function executeRule(current, previous) {
    var newCount = parseInt(current.getValue('option_year_count') || '0', 10);
    var oldCount = parseInt(previous.getValue('option_year_count') || '0', 10);

    // Only check on reduction
    if (newCount >= oldCount) {
        return;
    }

    // Check if any periods with sequence > newCount have child cost data
    // The cost data table may not exist yet
    var costTable = 'x_942105_costima_0_cost_line';
    var costGr = new GlideRecord(costTable);
    if (!costGr.isValid()) {
        return;
    }

    // Get periods that would be removed (sequence > newCount)
    var periodGr = new GlideRecord('x_942105_costima_0_period');
    periodGr.addQuery('proposal', current.getUniqueValue());
    periodGr.addQuery('period_sequence', '>', newCount);
    periodGr.query();

    while (periodGr.next()) {
        var costCheck = new GlideRecord(costTable);
        costCheck.addQuery('period', periodGr.getUniqueValue());
        costCheck.setLimit(1);
        costCheck.query();

        if (costCheck.hasNext()) {
            gs.addErrorMessage(
                'Cannot reduce option year count. Period "' +
                periodGr.getValue('period_name') +
                '" (sequence ' + periodGr.getValue('period_sequence') +
                ') has associated cost data. Remove the cost data first.'
            );
            current.setAbortAction(true);
            return;
        }
    }
})(current, previous);
